 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (0, 2)]
    # The rectangle projects along each row and column. A marker on a line
    # suppresses the projection toward itself and leaves the opposite ray.
    for r in range(r0, r1 + 1):
        row_marks = [c for rr, c in marks if rr == r]
        if not any(c > c1 for c in row_marks):
            for c in range(c0):
                if grid[r][c] == 0: out[r][c] = 2
        if not any(c < c0 for c in row_marks):
            for c in range(c1 + 1, w):
                if grid[r][c] == 0: out[r][c] = 2
    for c in range(c0, c1 + 1):
        col_marks = [r for r, cc in marks if cc == c]
        if not any(r > r1 for r in col_marks):
            for r in range(r0):
                if grid[r][c] == 0: out[r][c] = 2
        if not any(r < r0 for r in col_marks):
            for r in range(r1 + 1, h):
                if grid[r][c] == 0: out[r][c] = 2
    return out
